package com.example.downloads;

/** Response headers for file downloads. */
public final class DownloadHeaders {
    private DownloadHeaders() {
    }

    public static String disposition(String filename) {
        return "attachment; filename=\"" + filename + "\"";
    }
}

package com.example.downloads;

import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

class DownloadHeadersTest {
    @Test
    void namesAttachment() {
        assertTrue(DownloadHeaders.disposition("a.txt").startsWith("attachment"));
    }
}
